#include "../linearprobing-cuda/linearprobing.cu"
#include "study_fixture.h"
#include <map>
#include <algorithm>
#include <filesystem>
#include <string>
#include <unistd.h>
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):3;auto batches=study_batches();KeyValue*table;cudaMalloc(&table,size_t(kHashTableCapacity)*8);std::vector<KeyValue*>dev;for(auto&b:batches){KeyValue*p;cudaMalloc(&p,b.pairs.size()*8);cudaMemcpy(p,b.pairs.data(),b.pairs.size()*8,cudaMemcpyHostToDevice);dev.push_back(p);}KeyValue*outputs[3];uint32_t*counts[3];for(int j=0;j<3;j++){cudaMalloc(&outputs[j],1027*8);cudaMalloc(&counts[j],4);}std::map<uint32_t,uint32_t>dict;std::vector<std::vector<KeyValue>>gold;std::vector<uint32_t>prefix{kHashTableCapacity,kEmpty,5,3,1027};for(int stage=0;stage<5;stage++){auto&a=batches[stage].pairs;prefix.push_back(a.size());for(auto z:a)prefix.push_back(z.key);for(auto z:a)prefix.push_back(z.value);for(auto z:a)if(stage==3)dict.erase(z.key);else dict[z.key]=z.value;if(stage>=2){std::vector<KeyValue>pairs;for(auto z:dict)pairs.push_back({z.first,z.second});gold.push_back(pairs);}}auto reset=[&](){cudaMemset(table,0xff,size_t(kHashTableCapacity)*8);for(int j=0;j<3;j++){cudaMemset(outputs[j],0xff,1027*8);cudaMemset(counts[j],0,4);}cudaDeviceSynchronize();};auto path=[&](int i){int batch=i<=2?i:i==4?3:4;if(i==3||i==5||i==7){int j=i==3?0:i==5?1:2;k_iterate_hashtable<<<(kHashTableCapacity+255)/256,256>>>(table,outputs[j],counts[j]);}else if(i==4)k_hashtable_delete<<<(batches[batch].pairs.size()+255)/256,256>>>(table,dev[batch],batches[batch].pairs.size());else k_hashtable_insert<<<(batches[batch].pairs.size()+255)/256,256>>>(table,dev[batch],batches[batch].pairs.size());};reset();for(int i=0;i<8;i++)path(i);cudaDeviceSynchronize();auto root=std::filesystem::path(__FILE__).parent_path().parent_path().parent_path();auto rawdir=root/".porting-state/portable_julia/raw_sidecars/linearprobing"/("cuda_"+std::to_string(getpid())+"_"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(rawdir);for(int trial=1;trial<=5;trial++){double times[8]={0};for(int z=0;z<rep;z++){reset();for(int i=0;i<8;i++){cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();path(i);cudaDeviceSynchronize();times[i]+=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;}}bool ok=cudaGetLastError()==cudaSuccess;std::vector<uint32_t>raw,canonical;for(int j=0;j<3;j++){uint32_t count;cudaMemcpy(&count,counts[j],4,cudaMemcpyDeviceToHost);if(count>1027)abort();std::vector<KeyValue>a(count);cudaMemcpy(a.data(),outputs[j],count*8,cudaMemcpyDeviceToHost);raw.push_back(count);for(auto z:a){raw.push_back(z.key);raw.push_back(z.value);}std::sort(a.begin(),a.end(),[](auto x,auto y){return x.key!=y.key?x.key<y.key:x.value<y.value;});ok&=a.size()==gold[j].size()&&memcmp(a.data(),gold[j].data(),a.size()*8)==0;canonical.push_back(count);for(auto z:a){canonical.push_back(z.key);canonical.push_back(z.value);}}std::string rawfile=(rawdir/("raw_trial"+std::to_string(trial)+".bin")).string();FILE*fp=fopen(rawfile.c_str(),"wb");fwrite(raw.data(),4,raw.size(),fp);fclose(fp);auto art=prefix;art.insert(art.end(),canonical.begin(),canonical.end());std::string file=std::string(getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".")+"/output_trial"+std::to_string(trial)+".bin";fp=fopen(file.c_str(),"wb");fwrite(art.data(),4,art.size(),fp);fclose(fp);double elapsed=0;for(auto t:times)elapsed+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0.0,\"max_rel_error\":0.0,\"timing_region\":\"sum8ordered_insert_delete_iterate_kernels_resetexcluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"per_path_times_seconds\":[",trial,elapsed,ok?"true":"false",canonical.size(),rep);for(int i=0;i<8;i++)printf(i?",%.17g":"%.17g",times[i]);printf("],\"raw_unordered_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"},\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",rawfile.c_str(),raw.size(),file.c_str(),art.size());if(!ok)return 2;}cudaFree(table);for(auto a:dev)cudaFree(a);for(int j=0;j<3;j++){cudaFree(outputs[j]);cudaFree(counts[j]);}}
